def transform(grid):
    if not grid:
        return grid

    R = len(grid)
    C = len(grid[0]) if R > 0 else 0

    visited = set()
    output = [[0] * C for _ in range(R)]

    for r in range(R):
        for c in range(C):
            if grid[r][c] != 0 and (r, c) not in visited:
                # Found a connected component of non-zero values
                component = []
                stack = [(r, c)]
                visited.add((r, c))

                while stack:
                    curr_r, curr_c = stack.pop()
                    component.append((curr_r, curr_c))

                    # Check 4 neighbors
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < R and 0 <= nc < C:
                            if grid[nr][nc] != 0 and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                stack.append((nr, nc))

                # Determine the value for this component
                if len(component) > 1:
                    # Connected component -> becomes 8 (Highlight)
                    val = 8
                else:
                    # Isolated component -> remains original value (7)
                    val = grid[r][c]

                # Update output grid
                for cr, cc in component:
                    output[cr][cc] = val

    return output
